#!/usr/bin/env bash
# Install the reference control plane from the checked-in Kustomize overlays.
#
#   ./scripts/install-control-plane.sh --lab            # OrbStack single-node lab
#   ./scripts/install-control-plane.sh --production     # 3-dnode TDengine + digest pins
#   ./scripts/install-control-plane.sh --dry-run        # print the merged manifests
#
# The lab path also creates the backup Secrets when missing and applies the
# local-lab backup wiring; the production path refuses to run until the real
# Secrets and the digest patch generated by scripts/publish-images.sh exist.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
DEPLOY="$ROOT/k8s_control_plane/deploy"
MODE=lab
DRY_RUN=0

for arg in "$@"; do
  case "$arg" in
    --lab) MODE=lab ;;
    --production) MODE=production ;;
    --dry-run) DRY_RUN=1 ;;
    *) echo "usage: $0 [--lab|--production] [--dry-run]" >&2; exit 2 ;;
  esac
done

command -v kubectl >/dev/null || { echo "kubectl not found" >&2; exit 1; }
OVERLAY="$ROOT/k8s_control_plane/overlays/$MODE"

if [ "$MODE" = production ]; then
  [ -f "$OVERLAY/images.patch.yaml" ] || {
    echo "missing $OVERLAY/images.patch.yaml — run scripts/publish-images.sh --registry <registry> --pin" >&2
    exit 1
  }
  for secret in "$DEPLOY/tdengine-credentials.yaml" "$DEPLOY/backup-rclone.yaml" "$DEPLOY/backup-signing-key.yaml"; do
    [ -f "$secret" ] || { echo "missing $secret — copy the .yaml.example and fill in real values" >&2; exit 1; }
  done
fi

MANIFESTS="$ROOT/.install-$MODE.yaml"
kubectl kustomize --load-restrictor=LoadRestrictionsNone "$OVERLAY" >"$MANIFESTS"
echo "rendered $OVERLAY -> $MANIFESTS ($(grep -c '^kind:' "$MANIFESTS") resources)"

if [ "$DRY_RUN" -eq 1 ]; then
  cat "$MANIFESTS"
  exit 0
fi

kubectl apply -f "$MANIFESTS"

if [ "$MODE" = lab ]; then
  if [ -n "${BACKUP_RCLONE_CONF_FILE:-}" ] && [ -n "${BACKUP_SIGNING_KEY_FILE:-}" ]; then
    kubectl -n match-control create secret generic match-backup-rclone \
      --from-file=rclone.conf="$BACKUP_RCLONE_CONF_FILE" --dry-run=client -o yaml | kubectl apply -f -
    kubectl -n match-control create secret generic match-backup-signing-key \
      --from-file=signing.key="$BACKUP_SIGNING_KEY_FILE" --dry-run=client -o yaml | kubectl apply -f -
    echo "backup Secrets applied from env-provided files"
  else
    echo "no BACKUP_RCLONE_CONF_FILE/BACKUP_SIGNING_KEY_FILE: run scripts/backup-local-lab.sh to wire the lab backup path"
  fi
  echo "next: ./scripts/ingress-frontdoor.sh start  (publishes the lab Ingresses on port 80)"
else
  kubectl apply -f "$DEPLOY/tdengine-credentials.yaml"
  kubectl apply -f "$DEPLOY/backup-rclone.yaml"
  kubectl apply -f "$DEPLOY/backup-signing-key.yaml"
  echo "production secrets applied; verify with: kubectl -n match-control rollout status deploy/match-manager"
fi
